import org.junit.jupiter.api.Test;

class GraphScopeOptimizerTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void positiveGraphIsLoweredBeforeJoinSelection() {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		TupleExpr plan = parse("SELECT * WHERE { VALUES ?s { <urn:s> } GRAPH <urn:g> { ?s <urn:p> ?o } }");
		strategy.optimize(plan, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		assertThat(graphs(plan)).isEmpty();
		assertThat(statements(plan)).singleElement().satisfies(statement -> {
			assertThat(statement.getScope()).isEqualTo(StatementPattern.Scope.NAMED_CONTEXTS);
			assertThat(statement.getContextVar().getValue()).isEqualTo(VF.createIRI("urn:g"));
			assertThat(statement.getSubjectVar().getValue()).isEqualTo(VF.createIRI("urn:s"));
		});
	}

	@Test
	void executedGraphStatementRetainsActualPlanCounters() {
		Statement data = VF.createStatement(VF.createIRI("urn:s"), VF.createIRI("urn:p"),
				VF.createIRI("urn:o"), VF.createIRI("urn:g"));
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new CloseableIteratorIteration<>(List.of(data).iterator());
			}
		}, null);
		strategy.setTrackResultSize(true);
		strategy.setTrackTime(true);
		TupleExpr plan = parse("SELECT * WHERE { GRAPH <urn:g> { ?s <urn:p> ?o } }");
		strategy.optimize(plan, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		try (CloseableIteration<BindingSet> result = strategy.precompile(plan)
				.evaluate(EmptyBindingSet.getInstance())) {
			assertThat(result.stream().count()).isEqualTo(1);
		}
		assertThat(statements(plan)).singleElement().satisfies(statement -> {
			assertThat(statement.getResultSizeActual()).isEqualTo(1);
			assertThat(statement.getTotalTimeNanosActual()).isGreaterThan(0);
		});
	}

	@Test
	void arbitraryBodiesAndRemoteGraphRetainTheirBoundaries() {
		for (String graphName : List.of("?g", "<urn:g>")) {
			for (String body : List.of("", "VALUES ?o { 1 }", "?s <urn:p> ?o FILTER(BOUND(?g))",
					"OPTIONAL { ?s <urn:p> ?o }", "{ SELECT ?o WHERE { ?s <urn:p> ?o } }")) {
				DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
				TupleExpr plan = parse("SELECT * WHERE { GRAPH " + graphName + " { " + body + " } }");
				strategy.optimize(plan, new EvaluationStatistics(), EmptyBindingSet.getInstance());
				assertThat(graphs(plan)).as(graphName + " / " + body).hasSize(1);
			}
		}
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		TupleExpr remote = parse("SELECT * WHERE { SERVICE <urn:remote> { GRAPH <urn:g> { ?s <urn:p> ?o } } }");
		strategy.optimize(remote, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		assertThat(graphs(remote)).hasSize(1);
	}

	@Test
	void annotatedStatementSubclassesRetainTheirIdentity() {
		StatementPattern annotated = new AnnotatedStatement();
		Var graphName = Var.of("g", VF.createIRI("urn:g"), false, true);
		assertThat(graphName.isConstant()).isTrue();
		TupleExpr plan = new QueryRoot(new Graph(graphName, annotated));
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		strategy.optimize(plan, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		assertThat(graphs(plan)).hasSize(1);
		assertThat(statements(plan)).containsExactly(annotated);
	}

	@Test
	void defaultGraphAliasesAndDatasetMembershipRetainGraphScope() {
		assertGraphRetained(RDF4J.NIL, null);
		assertGraphRetained(SESAME.NIL, null);
		assertGraphRetained(VF.createIRI("urn:g"), new SimpleDataset());

		for (IRI alias : List.of(RDF4J.NIL, SESAME.NIL)) {
			SimpleDataset dataset = new SimpleDataset();
			dataset.addNamedGraph(alias);
			assertGraphRetained(VF.createIRI("urn:g"), dataset);
		}
	}

	private static void assertGraphRetained(Value graphName, Dataset dataset) {
		Var graph = Var.of("g", graphName, false, true);
		TupleExpr plan = new QueryRoot(new Graph(graph, new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"))));
		new GraphScopeOptimizer().optimize(plan, dataset, EmptyBindingSet.getInstance());
		assertThat(graphs(plan)).hasSize(1);
	}

	private static TupleExpr parse(String query) {
		return new QueryRoot(QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr());
	}

	private static final class AnnotatedStatement extends StatementPattern {
		private static final long serialVersionUID = 1L;

		private AnnotatedStatement() {
			super(new Var("s"), new Var("p"), new Var("o"));
		}
	}

	private static List<Graph> graphs(TupleExpr plan) {
		List<Graph> result = new ArrayList<>();
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Graph graph) {
				result.add(graph);
				super.meet(graph);
			}
		});
		return result;
	}

	private static List<StatementPattern> statements(TupleExpr plan) {
		List<StatementPattern> result = new ArrayList<>();
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern statement) {
				result.add(statement);
			}
		});
		return result;
	}
}
